    <div class="topbar-center"><button data-act="upload">사진 업로드</button><button data-act="undo">↶ Undo</button><button data-act="redo">↷ Redo</button><button data-act="compare" class="hold-btn">원본 비교</button><button data-act="saveProject">프로젝트 저장</button><button data-act="loadProject">불러오기</button></div>
