    try{const {imageData}=await rasterMain();let transparent=0;for(let i=3;i<imageData.data.length;i+=4)if(imageData.data[i]<245)transparent++;if(transparent>imageData.width*imageData.height*.02){const m=alphaSubject(imageData);project.maskDataUrl=canvasToDataUrl(maskToCanvas(m,imageData.width,imageData.height,1));project.lighting.enabled=true;toast('투명 알파를 감지해 정밀 외곽 마스크를 만들었습니다.','success')}}catch(e){console.warn(e)}
