  function renderPresets(){sectionTitle('Smart Presets','40+ 프리셋. 먼저 40~60% 강도로 시작한 뒤 미세 조정하세요.');const ai=html('button',{class:'wide primary soft',text:'✨ 사진 분석 후 프리셋 추천'});ai.onclick=recommendPreset;panel.append(ai,makeRange({label:'프리셋 강도',min:0,max:100,value:project.preset?.intensity??60,suffix:'%',onStart:()=>snapshot('프리셋 강도'),onInput:v=>{project.preset.intensity=v;changed()}}));for(const cat of PRESET_CATEGORIES){panel.append(html('div',{class:'mini-heading',text:cat}));const grid=html('div',{class:'preset-grid'});PHOTO_PRESETS.filter(p=>p.category===cat).forEach(p=>{const b=html('button',{class:`preset-card ${project.preset?.id===p.id?'active':''}`});b.innerHTML=`<span class="preset-swatch ${cat.toLowerCase()}"></span><b>${p.name}</b><small>${p.hint||cat}</small>`;b.onclick=()=>{snapshot(`프리셋: ${p.name}`);project.preset={id:p.id,intensity:project.preset?.intensity??60};project.adjustments={...p.values};changed({panelToo:true})};grid.append(b)});panel.append(grid)}}
