    const aiBox=html('div',{class:'ai-edge-box'}),ai=html('button',{class:'wide primary',text:'🧠 AI 정밀 캐릭터 인식'});ai.onclick=()=>aiSelect(ai);aiBox.append(ai,html('small',{text:'일반 배경 사진에서 캐릭터 실루엣 초안을 생성합니다. 최초 1회는 AI 모델 다운로드 때문에 시간이 걸릴 수 있습니다.'}));panel.append(aiBox)
    const quick=html('div',{class:'button-grid'}),auto=html('button',{text:'⚡ 빠른 자동 초안'}),wand=html('button',{text:'🪄 마법봉'}),add=html('button',{text:'+ 브러시'}),sub=html('button',{text:'− 브러시'});auto.onclick=autoSelect;wand.onclick=()=>setTool('wand');add.onclick=()=>setTool('mask-add');sub.onclick=()=>setTool('mask-remove');quick.append(auto,wand,add,sub);panel.append(quick)
    const manual=html('div',{class:'manual-edge-card'});manual.append(html('b',{text:'수동 외곽선 — 점과 선으로 직접 지정'}));const tools=html('div',{class:'button-grid'});manual.append(tools)
