  async function exportFixedPhoto(key,status,button){
    if(!mainLayer()){toast('먼저 사진을 업로드해주세요.','error');return}
    const preset=PHOTO_EXPORT_PRESETS[key];const old=button?.textContent;if(button){button.disabled=true;button.textContent='렌더링 중…'}
    try{
      const c=await renderPhotoProject({...project,canvas:{...project.canvas,viewMode:'final'}},{width:preset.width,height:preset.height,viewMode:'final'})
      const result=await optimizePngFixedSize(c,preset.maxBytes,(p,r)=>{if(status)status.textContent=`${Math.round(p*100)}% · 현재 ${(r.bytes/1024).toFixed(1)}KB · ${r.qualityLabel}`})
      if(!result.metTarget)throw new Error(`${preset.width}×${preset.height} 크기를 유지한 채 50KB 이하로 만들지 못했습니다. 저장을 중단했습니다.`)
      const name=`profile-${key}-${preset.width}x${preset.height}-v2.1.png`;downloadBlob(result.blob,name)
      if(status){status.textContent=`${preset.label}: ${describeOptimizerResult(result)} ✅ 50KB 이하`;status.className='optimizer-status ok'}
      toast(`${preset.label} 최적화 저장 완료`,'success')
    }catch(e){toast(e.message,'error');if(status)status.textContent=`오류: ${e.message}`}
    finally{if(button){button.disabled=false;button.textContent=old}}
  }

