  function renderHistory(){const el=$('#history-list',root);el.innerHTML='';const labels=history.list().slice(-12).reverse();if(!labels.length)el.append(html('div',{class:'empty-small',text:'변경 기록이 없습니다.'}));labels.forEach((x,i)=>el.append(html('div',{class:'history-row',text:`${i===0?'●':'○'} ${x}`})))}
  function updateToolStatus(){const names={select:'선택/이동',wand:'Magic Wand','mask-add':'마스크 추가 브러시','mask-remove':'마스크 제거 브러시',polygon:'Polygon 수동 외곽선',bezier:'Curve 수동 외곽선',pen:'Pen','glow-pen':'Glow Pen','sparkle-pen':'Sparkle Pen'};$('#toolStatus',root).textContent=names[activeTool]||activeTool}

  function scheduleRender(){const seq=++renderSeq;requestAnimationFrame(async()=>{if(!destroyed&&seq===renderSeq)await renderCanvas(seq)})}
  async function renderCanvas(seq){
    const max=920,scale=Math.min(1,max/Math.max(project.canvas.width,project.canvas.height)),w=Math.max(220,Math.round(project.canvas.width*scale)),h=Math.max(220,Math.round(project.canvas.height*scale));canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#202229';ctx.fillRect(0,0,w,h)
    if(compare&&mainLayer()){try{const im=await loadImage(mainLayer().dataUrl);drawImageFit(ctx,im,w,h,'cover',{})}catch{}return}
    try{const out=await renderPhotoProject(project,{width:w,height:h,viewMode:project.canvas.viewMode});if(seq!==renderSeq)return;ctx.clearRect(0,0,w,h);ctx.drawImage(out,0,0);drawManualPathOverlay(ctx,w,h)}catch(e){console.warn(e)}
    $('.drop-hint',stage).style.display=mainLayer()?'none':'flex';$('#canvasInfo',root).textContent=`${project.canvas.width} × ${project.canvas.height} · Preview ${w} × ${h}`
  }
  function drawManualPathOverlay(ctx,w,h){const pts=project.manualPath?.points||[];if(!pts.length||!['polygon','bezier'].includes(activeTool))return;ctx.save();ctx.strokeStyle='#6df6ff';ctx.fillStyle='#ffffff';ctx.lineWidth=2;ctx.shadowColor='#000';ctx.shadowBlur=3;ctx.beginPath();pts.forEach((p,i)=>{const x=p.x*w,y=p.y*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(project.manualPath.closed)ctx.closePath();ctx.stroke();pts.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x*w,p.y*h,i===0?5:4,0,Math.PI*2);ctx.fillStyle=i===0?'#ffde7d':'#ffffff';ctx.fill()});ctx.restore()}
  function canvasPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*project.canvas.width,y:(e.clientY-r.top)/r.height*project.canvas.height,px:(e.clientX-r.left)/r.width,py:(e.clientY-r.top)/r.height}}
  function nearestManualPoint(p){const pts=project.manualPath.points;let bi=-1,bd=18;for(let i=0;i<pts.length;i++){const d=Math.hypot((pts[i].x-p.px)*canvas.clientWidth,(pts[i].y-p.py)*canvas.clientHeight);if(d<bd){bd=d;bi=i}}return bi}
  async function addPathPoint(p){let x=p.x,y=p.y;if(project.manualPath.edgeSnap){edgeSource=edgeSource||await rasterMain();const q=snapPointToEdge(edgeSource.imageData,x,y,project.manualPath.snapRadius);x=q.x;y=q.y}project.manualPath.points.push({x:x/project.canvas.width,y:y/project.canvas.height});project.manualPath.closed=false;scheduleRender();renderPanel()}
  canvas.addEventListener('pointerdown',async e=>{if(!mainLayer()&&activeTool!=='select')return;const p=canvasPoint(e)
    if(activeTool==='wand'){await useMagicWand(p.x,p.y);setTool('select');return}
    if(activeTool==='polygon'||activeTool==='bezier'){const ni=nearestManualPoint(p);if(ni>=0){dragPoint=ni;canvas.setPointerCapture(e.pointerId);return}snapshot('외곽선 점 추가');await addPathPoint(p);return}
    if(activeTool==='mask-add'||activeTool==='mask-remove'){snapshot(activeTool==='mask-add'?'마스크 추가':'마스크 제거');maskDrawing=true;canvas.setPointerCapture(e.pointerId);await paintMask(p);return}
    if(['pen','glow-pen','sparkle-pen'].includes(activeTool)){let l=selectedLayer();if(!l||l.type!=='drawing'){snapshot('그리기 레이어');l={id:uid('draw'),type:'drawing',name:'Drawing',visible:true,opacity:1,strokes:[]};project.layers.push(l);project.selectedLayerId=l.id}drawingStroke={color:project.brush.color,size:project.brush.size,opacity:project.brush.opacity/100,glow:activeTool!=='pen',sparkle:activeTool==='sparkle-pen',points:[p]};l.strokes.push(drawingStroke);canvas.setPointerCapture(e.pointerId);scheduleRender();return}
    const l=selectedLayer();if(l?.transform){snapshot('레이어 이동');moving={layer:l,start:p,ox:l.transform.x||0,oy:l.transform.y||0};canvas.setPointerCapture(e.pointerId)}})
  canvas.addEventListener('pointermove',async e=>{const p=canvasPoint(e);if(dragPoint>=0){project.manualPath.points[dragPoint]={x:p.x/project.canvas.width,y:p.y/project.canvas.height};scheduleRender()}else if(maskDrawing)await paintMask(p);else if(drawingStroke){drawingStroke.points.push(p);scheduleRender()}else if(moving){moving.layer.transform.x=moving.ox+(p.x-moving.start.x);moving.layer.transform.y=moving.oy+(p.y-moving.start.y);scheduleRender();renderLayerProps()}})
  canvas.addEventListener('pointerup',()=>{if(dragPoint>=0){snapshot('외곽선 점 이동');dragPoint=-1;autosave()}if(maskDrawing){maskDrawing=false;project.maskDataUrl=maskEditCanvas.toDataURL('image/png');changed()}if(drawingStroke){drawingStroke=null;changed()}if(moving){moving=null;changed()}})
  async function paintMask(p){const c=await ensureMaskCanvas(),ctx=c.getContext('2d');ctx.save();ctx.globalCompositeOperation=activeTool==='mask-remove'?'destination-out':'source-over';ctx.fillStyle='#fff';ctx.globalAlpha=.9;ctx.beginPath();ctx.arc(p.x,p.y,project.maskSettings.brushSize/2,0,Math.PI*2);ctx.fill();ctx.restore();project.maskDataUrl=c.toDataURL('image/png');scheduleRender()}
  stage.addEventListener('dragover',e=>e.preventDefault());stage.addEventListener('drop',async e=>{e.preventDefault();const f=e.dataTransfer.files?.[0];if(f?.type.startsWith('image/'))await setMainPhoto(f)})
  async function exportImage(type){if(!mainLayer()){toast('먼저 사진을 업로드해주세요.','error');return}try{const c=await renderPhotoProject({...project,canvas:{...project.canvas,viewMode:'final'}},{width:project.canvas.width,height:project.canvas.height,viewMode:'final'});c.toBlob(blob=>{if(blob){downloadBlob(blob,`profile-retouch-v2.1.${type==='png'?'png':'jpg'}`);toast(`${type.toUpperCase()} 저장 완료`,'success')}},type==='png'?'image/png':'image/jpeg',.96)}catch(e){toast(e.message,'error')}}
  function onKey(e){const tag=e.target?.tagName?.toLowerCase();if(['input','textarea','select'].includes(tag)&&!(e.ctrlKey||e.metaKey))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();const p=e.shiftKey?history.redo(project):history.undo(project);if(p)setProject(p)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();const p=history.redo(project);if(p)setProject(p)}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProjectFile(project)}else if(e.key.toLowerCase()==='w'&&!e.ctrlKey)setTool('wand');else if(e.key.toLowerCase()==='p'&&!e.ctrlKey){project.manualPath.mode='polygon';setTool('polygon');activeTab='edge';renderPanel()}else if(e.key.toLowerCase()==='c'&&!e.ctrlKey){project.manualPath.mode='bezier';setTool('bezier');activeTab='edge';renderPanel()}else if(e.key.toLowerCase()==='b'&&!e.ctrlKey){setTool('pen');activeTab='draw';renderPanel()}else if(e.key.toLowerCase()==='t'&&!e.ctrlKey)addTextLayer();else if(e.key==='Delete'){if(['polygon','bezier'].includes(activeTool)&&project.manualPath.points.length){snapshot('외곽선 점 삭제');project.manualPath.points.pop();scheduleRender();renderPanel();return}const l=selectedLayer();if(l&&l.role!=='main'){snapshot('레이어 삭제');project.layers=project.layers.filter(x=>x.id!==l.id);project.selectedLayerId=null;changed()}}}
  async function onPaste(e){const item=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(item){const f=item.getAsFile();if(f)await setMainPhoto(f)}}
  async function init(){bindTop();window.addEventListener('keydown',onKey);window.addEventListener('paste',onPaste);await loadFonts();frameAssets=await getAssets('frame').catch(()=>[]);renderPanel();renderLayerList();renderLayerProps();renderHistory();updateToolStatus();syncViewButtons();scheduleRender();autosave()}
  init();return {destroy(){destroyed=true;window.removeEventListener('keydown',onKey);window.removeEventListener('paste',onPaste)}}
